import numpy as np
import time


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        P = np.array(start, dtype=float, copy=True)
    else:
        k = int(np.ceil(np.sqrt(32)))
        pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:32]
        P = np.array([[x, y, 0.02] for x, y in pts], dtype=float)

    n = P.shape[0]
    x = P[:, 0].copy()
    y = P[:, 1].copy()
    r = P[:, 2].copy()

    def feasible_scale(x, y, r):
        s = 1.0
        # walls
        for i in range(n):
            ri = r[i]
            if ri <= 0:
                return 0.0
            vals = (x[i] / ri, (1.0 - x[i]) / ri, y[i] / ri, (1.0 - y[i]) / ri)
            m = min(vals)
            if m < s:
                s = m
        # pairs
        for i in range(n):
            xi, yi, ri = x[i], y[i], r[i]
            for j in range(i + 1, n):
                dx = xi - x[j]
                dy = yi - y[j]
                d = (dx * dx + dy * dy) ** 0.5
                rs = ri + r[j]
                if rs > 0:
                    q = d / rs
                    if q < s:
                        s = q
        return s

    def separate(x, y, r, sweeps):
        for _ in range(sweeps):
            for i in range(n):
                xi, yi, ri = x[i], y[i], r[i]
                for j in range(i + 1, n):
                    dx = xi - x[j]
                    dy = yi - y[j]
                    d2 = dx * dx + dy * dy
                    rs = ri + r[j]
                    if d2 < rs * rs:
                        d = d2 ** 0.5
                        if d < 1e-12:
                            # deterministic tiny nudge
                            dx, dy, d = 1e-6, 0.0, 1e-6
                        push = 0.5 * (rs - d)
                        ux = dx / d
                        uy = dy / d
                        x[i] += ux * push
                        y[i] += uy * push
                        x[j] -= ux * push
                        y[j] -= uy * push
                        xi, yi = x[i], y[i]
            # clamp to walls
            for i in range(n):
                ri = r[i]
                if x[i] < ri:
                    x[i] = ri
                elif x[i] > 1.0 - ri:
                    x[i] = 1.0 - ri
                if y[i] < ri:
                    y[i] = ri
                elif y[i] > 1.0 - ri:
                    y[i] = 1.0 - ri

    best_sum = -1.0
    best = None

    # initial feasibility check / best
    s0 = feasible_scale(x, y, r)
    if s0 >= 1.0:
        best_sum = r.sum()
        best = np.column_stack([x, y, r]).copy()

    for it in range(400):
        if time.process_time() > deadline:
            break
        r = r * 1.02
        separate(x, y, r, 50)
        s = feasible_scale(x, y, r)
        if s < 1.0:
            r = r * (0.999 * s)
        else:
            # feasible; maybe try to keep
            pass
        # evaluate
        s2 = feasible_scale(x, y, r)
        if s2 >= 1.0:
            tot = r.sum()
            if tot > best_sum:
                best_sum = tot
                best = np.column_stack([x, y, r]).copy()

    if best is None:
        # fall back to start shrunk
        best = np.column_stack([x, y, r]).copy()
        s = feasible_scale(best[:, 0], best[:, 1], best[:, 2])
        if s < 1.0:
            best[:, 2] *= 0.999 * s

    # final safety shrink
    bx = best[:, 0].copy()
    by = best[:, 1].copy()
    br = best[:, 2].copy()
    s = feasible_scale(bx, by, br)
    if s < 1.0:
        br *= 0.999 * s
    br *= (1.0 - 1e-9)
    # re-clamp centers to ensure inside with shrunk radii
    for i in range(n):
        ri = br[i]
        if bx[i] < ri:
            bx[i] = ri
        elif bx[i] > 1.0 - ri:
            bx[i] = 1.0 - ri
        if by[i] < ri:
            by[i] = ri
        elif by[i] > 1.0 - ri:
            by[i] = 1.0 - ri

    return np.column_stack([bx, by, br])
